#!/usr/bin/env python3
from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')
if 'data-uvis-ifa-central="1"' in s:
    print('Central IFA já integrada.')
    raise SystemExit(0)

old="""        document.addEventListener('keydown',function(e){if(e.key==='Enter'&&e.target&&e.target.id==='q')complementar();},true);\n      })();`,'</scr','ipt>'].join('');\n      s=s.replace(/<\\/body>/i,ponte+'</body>');\n"""
if old not in s:
    raise SystemExit('Âncora da ponte da Central de Consultas não localizada.')

new="""        document.addEventListener('keydown',function(e){if(e.key==='Enter'&&e.target&&e.target.id==='q')complementar();},true);\n      })();`,'</scr','ipt>'].join('');\n      var ponteIfa='<scr'+'ipt src=\"./ifa-lookup-shared.js\"></scr'+'ipt><scr'+'ipt>'+String.raw`(function(){\n        'use strict';\n        if(window.__UVIS_IFA_CENTRAL__)return;window.__UVIS_IFA_CENTRAL__=true;\n        function esc(v){return String(v==null?'':v).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c];});}\n        function E(id){return document.getElementById(id);}\n        function ifaButton(){return document.querySelector('.mode[data-mode=\"ifa\"]');}\n        function ativo(){var b=ifaButton();return !!(b&&b.classList.contains('on'));}\n        function status(text,ok){var st=E('status');if(st){st.className='status '+(ok?'ok':'');st.textContent=text||'';}}\n        function ativar(){\n          document.querySelectorAll('.mode').forEach(function(x){x.classList.remove('on');});\n          var b=ifaButton();if(b)b.classList.add('on');\n          var q=E('q');if(q){q.value='';q.placeholder='IFA, fabricante, código, processo Anvisa ou CNPJ do peticionante';q.focus();}\n          var host=E('results');if(host){host.className='';host.innerHTML='<div class=\"empty\"><b>Consulta de IFA</b><br>Pesquise o insumo, fabricante, código do fabricante, processo Anvisa ou CNPJ do peticionante.</div>';}\n          status('Consulta específica à visão pública de IFA da Anvisa. Ausência de resultado não prova ausência de regularização.',false);\n        }\n        function instalar(){\n          if(ifaButton())return;var modos=document.querySelectorAll('.mode');if(!modos.length)return;\n          var b=document.createElement('button');b.type='button';b.className='mode';b.setAttribute('data-mode','ifa');b.setAttribute('data-uvis-ifa-central','1');b.textContent='IFA';\n          b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();ativar();});\n          modos[modos.length-1].parentElement.appendChild(b);\n        }\n        function artigo(r){\n          var kv=[['Fabricante do IFA',r.fabricante_ifa],['Código do fabricante',r.codigo_fabricante_ifa],['País',r.pais_fabricante],['Processo Anvisa (IFA)',r.processo_anvisa],['Detentor / peticionante',r.detentor_peticionante],['CNPJ do peticionante',r.cnpj_detentor_peticionante],['Assunto',r.assunto]];\n          return '<article class=\"result\"><h4>'+esc(r.ifa||'IFA')+'</h4><div class=\"kv\">'+kv.filter(function(x){return x[1];}).map(function(x){return '<b>'+esc(x[0])+'</b><span>'+esc(x[1])+'</span>';}).join('')+'</div></article>';\n        }\n        function consultar(){\n          var q=E('q'),host=E('results'),term=(q&&q.value||'').trim();if(!term){status('Informe um termo para consulta.',false);return;}\n          if(!window.UvisIfaLookup||typeof window.UvisIfaLookup.search!=='function'){status('O motor compartilhado de IFA ainda não está disponível. Recarregue o aplicativo com conexão.',false);return;}\n          status('Consultando a base pública de IFA…',false);if(host)host.innerHTML='';\n          window.UvisIfaLookup.search(term,{limit:50}).then(function(result){\n            var list=(result.resultados||[]).map(function(x){return window.UvisIfaLookup.formatResult(x);});\n            if(!list.length){if(host)host.innerHTML='<div class=\"empty\"><b>Nenhum resultado localizado.</b><br>Isso não equivale a ausência de regularização do IFA por outra via.</div>';status('Consulta concluída sem resultado nesta visão pública.',true);return;}\n            var html='<div class=\"summary\"><div class=\"sum\"><b>'+list.length+'</b><span>resultado(s) de IFA</span></div><div class=\"sum\"><b>Anvisa</b><span>fonte pública</span></div></div><div class=\"group\"><div class=\"grouphead\"><h3>IFA — Insumo Farmacêutico Ativo</h3><span>'+list.length+' resultado(s)</span></div>'+list.map(artigo).join('')+'</div>';\n            if(result.observacao)html+='<p class=\"muted\">'+esc(result.observacao)+'</p>';if(result.fonte)html+='<p class=\"muted\"><b>Fonte:</b> '+esc(result.fonte)+(result.gerado_em?' · base gerada em '+esc(new Date(result.gerado_em).toLocaleString('pt-BR')):'')+'.</p>';\n            if(host){host.className='';host.innerHTML=html;}status('Consulta concluída. Confira o fabricante do IFA e o Processo Anvisa antes de utilizar a informação.',true);\n          }).catch(function(err){status('Não foi possível concluir a consulta IFA: '+((err&&err.message)||err),false);});\n        }\n        document.addEventListener('click',function(e){\n          var mode=e.target&&e.target.closest&&e.target.closest('.mode');if(mode&&mode.getAttribute('data-mode')!=='ifa'){var ib=ifaButton();if(ib)ib.classList.remove('on');}\n          if(ativo()&&e.target&&e.target.closest&&e.target.closest('#search')){e.preventDefault();e.stopImmediatePropagation();consultar();}\n        },true);\n        document.addEventListener('keydown',function(e){if(ativo()&&e.key==='Enter'&&e.target&&e.target.id==='q'){e.preventDefault();e.stopImmediatePropagation();consultar();}},true);\n        if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',instalar);else instalar();\n      })();`+'</scr'+'ipt>';\n      s=s.replace(/<\\/body>/i,ponte+ponteIfa+'</body>');\n"""
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
print('Central IFA integrada ao index.html.')
